#!/usr/bin/env python3
"""Own-worktree CPU build cache; retain the installed compiler and its flags."""
import hashlib,json,os,re,shlex,subprocess,sys,tempfile,time
from pathlib import Path
ROOT=Path('/Users/ericfode/src/knot/.claude/worktrees/campaign-descent-2')
CACHE=ROOT/'.local/descent-2/native-cache'
REAL=Path('/Applications/Xcode.app/Contents/Developer/Toolchains/XcodeDefault.xctoolchain/usr/bin/clang')
SDK=Path('/Applications/Xcode.app/Contents/Developer/Platforms/MacOSX.platform/Developer/SDKs/MacOSX.sdk')
POLICY=['/usr/sbin/taskpolicy','-a','-t','0','-l','0']
ARGS=sys.argv[1:]
START=time.monotonic()

def sha(data):return hashlib.sha256(data).hexdigest()
def log(row):
    row.update(seconds=round(time.monotonic()-START,6),pid=os.getpid())
    with (CACHE/'events.jsonl').open('a') as f:f.write(json.dumps(row,sort_keys=True)+'\n')
def real():return subprocess.run([*POLICY,str(REAL),*ARGS]).returncode

def main():
    # All other compiler modes are forwarded without caching.
    if len(ARGS)!=7 or ARGS[:2]!=['-std=c11','-O3'] or ARGS[3:6]!=['-lpthread','-lm','-o']:
        return real()
    source=Path(ARGS[2]);output=Path(ARGS[6])
    if source.suffix!='.c' or not source.is_file() or not output.resolve().is_relative_to(ROOT/'.local'):
        return real()
    cpp=subprocess.run([str(REAL),'-std=c11','-O3','-E','-P',str(source)],capture_output=True)
    if cpp.returncode or cpp.stderr:
        log({'kind':'bypass','reason':'preprocessing diagnostic','source':str(source)})
        return real()
    plan=subprocess.run([str(REAL),'-###',*ARGS],capture_output=True)
    if plan.returncode:return real()
    canonical_plan=plan.stderr.decode().replace(str(source),'$SOURCE').replace(str(output),'$OUTPUT')
    # Only this strict release command is cached: no debug/coverage flags.
    # Preserve filename; ignore temporary object and inactive debug-directory metadata.
    for line in plan.stderr.decode().splitlines():
        if '"-cc1"' in line:
            command=shlex.split(line);obj=command[command.index('-o')+1]
            canonical_plan=canonical_plan.replace(obj,'$OBJECT')
    canonical_plan=re.sub(r'-f(?:debug|coverage)-compilation-dir=[^"]+', '-fmetadata-compilation-dir=$CWD', canonical_plan)
    if re.search(rb'__builtin_(?:FILE|LINE|source_location)\b',cpp.stdout):return real()
    resource=subprocess.check_output([str(REAL),'-print-resource-dir'],text=True).strip()
    linked=[REAL,REAL.with_name('ld'),SDK/'usr/lib/libSystem.tbd',
            SDK/'usr/lib/libpthread.tbd',SDK/'usr/lib/libm.tbd',REAL.parent.parent/'lib/libLTO.dylib',
            Path(resource)/'lib/darwin/libclang_rt.osx.a']
    identity={str(p):sha(p.read_bytes()) for p in linked if p.is_file()}
    assert str(REAL) in identity and str(REAL.with_name('ld')) in identity
    key_data={'schema':1,'preprocessed_sha256':sha(cpp.stdout),'compiler_and_link_inputs':identity,
              'plan':canonical_plan,'flags':['-std=c11','-O3','-lpthread','-lm'],
              'sdk':str(SDK),'policy':POLICY,
              'environment':{k:os.environ.get(k) for k in ['SDKROOT','MACOSX_DEPLOYMENT_TARGET','CPATH','C_INCLUDE_PATH','LIBRARY_PATH','COMPILER_PATH','CCC_OVERRIDE_OPTIONS']}}
    key=sha(json.dumps(key_data,sort_keys=True).encode())
    entry=CACHE/key; metadata=entry/'build.json';binary=entry/'binary'
    event={'key':key,'source':str(source),'source_sha256':sha(source.read_bytes()),
           'preprocessed_sha256':key_data['preprocessed_sha256'],'output':str(output)}
    if metadata.is_file() and binary.is_file():
        record=json.loads(metadata.read_text())
        if record['key']==key and record['inputs']==key_data and record['binary_sha256']==sha(binary.read_bytes()):
            with tempfile.NamedTemporaryFile(dir=output.parent,prefix='.native-cache-',delete=False) as f:
                temp=Path(f.name);f.write(binary.read_bytes())
            temp.chmod(record['mode']);temp.replace(output)
            log({**event,'kind':'hit','binary_sha256':record['binary_sha256']})
            return 0
    built=subprocess.run([*POLICY,str(REAL),*ARGS],capture_output=True)
    sys.stdout.buffer.write(built.stdout);sys.stderr.buffer.write(built.stderr)
    if built.returncode==0 and not built.stdout and not built.stderr and output.is_file():
        entry.mkdir(exist_ok=True)
        with tempfile.NamedTemporaryFile(dir=entry,prefix='.binary-',delete=False) as f:
            temp=Path(f.name);f.write(output.read_bytes())
        mode=output.stat().st_mode&0o777;temp.chmod(mode);temp.replace(binary)
        record={'key':key,'inputs':key_data,'binary_sha256':sha(binary.read_bytes()),'mode':mode,
                'actual_compiler_exit':0,'actual_compiler_stdout':'','actual_compiler_stderr':''}
        with tempfile.NamedTemporaryFile(dir=entry,prefix='.record-',mode='w',delete=False) as f:
            json.dump(record,f,indent=2,sort_keys=True);f.write('\n');temp=Path(f.name)
        temp.replace(metadata)
        log({**event,'kind':'miss-built','binary_sha256':record['binary_sha256']})
    else:log({**event,'kind':'miss-failed','exit':built.returncode})
    return built.returncode

try:code=main()
except Exception as e:
    log({'kind':'bypass','reason':type(e).__name__+': '+str(e)})
    code=real()
sys.exit(code)
